if _sec_distance:
    dc1,dc2,dc3 = st.columns([1,1,1])
    bc_dict = dict(zip(block_centroids["Block_APO"], zip(block_centroids["lat"],block_centroids["lng"])))
    from_options = list(REP_HOME.keys()) + sorted(block_centroids["Block_APO"].tolist())
